          const index = updatedMessages.findIndex(m => m.id === newMsg.id);
          if (index !== -1) {
            updatedMessages[index] = { ...updatedMessages[index], status: 'sent' };
          }
          return { ...prev, [selectedChatContact.phone]: updatedMessages };
        });
        addNotification(`📤 Message sent to ${selectedChatContact.name}`);
      } else {
        setChatMessages(prev => {
          const updatedMessages = [...(prev[selectedChatContact.phone] || [])];
          const index = updatedMessages.findIndex(m => m.id === newMsg.id);
          if (index !== -1) {
            updatedMessages[index] = { ...updatedMessages[index], status: 'failed' };
          }
          return { ...prev, [selectedChatContact.phone]: updatedMessages };
        });
        addNotification('❌ Failed to send message.', 'error');
      }
    } catch (error) {
      console.error('Send message error:', error);
      addNotification('❌ Error sending message.', 'error');
    } finally {
      setIsSendingMessage(false);
    }
  };

  const selectChatContact = (contact) => {
    setSelectedChatContact(contact);
    setChatContacts(prev => prev.map(c => 
      c.phone === contact.phone ? { ...c, unread: 0 } : c
    ));
  };

  const goBackToContactList = () => {
    setSelectedChatContact(null);
  };

  // ============================================
  // ACTIVATE SERVICE
  // ============================================

  const activateService = async () => {
    setIsLoading(true);
    setResponseMessage('');
    setIsSuccess(false);
    setErrorDetails('');

    try {
      const result = await callApi('/activate', 'POST', { penzi: activationKeyword || 'PENZI' });

      if (result && result.status === 'success') {
        // Show the system response message
        setSystemResponseMessage(STEPS[0].systemMessage);
        setShowSystemResponse(true);

        setActivationDone(true);
        setResponseMessage('✅ Service activated successfully!');
        setIsSuccess(true);
        setCompletedSteps(prev => new Set([...prev, 0]));
        addNotification('✅ Service activated!');
        setMyPhone('0712345678');
        setActivationKeyword('');
      } else {
        setResponseMessage('❌ Invalid activation keyword. Please enter PENZI to continue.');
        setIsSuccess(false);
        setErrorDetails('Invalid activation keyword. Please enter PENZI to continue.');
        addNotification('❌ Invalid activation keyword', 'error');
      }
    } catch (error) {
      console.error('❌ Activation Error:', error);
      setResponseMessage('❌ Network error. Please check your connection.');
      setIsSuccess(false);
      setErrorDetails(error.message);
      addNotification('❌ Network error', 'error');
    } finally {
      setIsLoading(false);
    }
  };

  // ============================================
  // PROCEED TO REGISTRATION (START Button)
  // ============================================

  const proceedToRegistration = () => {
    setCurrentStep(1);
    setShowSystemResponse(false);
    addNotification('📝 Proceeding to Registration...');
  };

  // ============================================
  // GO TO NEXT STEP (Registration)
  // ============================================

  const goToNextStep = async () => {
    const step = STEPS[currentStep];

    // If user exists error, go to dashboard
    if (userExistsError) {
      setShowMainMenu(true);
      setIsLoggedIn(true);
      setUserExistsError(false);
      setRegistrationError('');
      return;
    }

    // Check if we need to register the user
    if (step.isRegistration) {
      setIsLoading(true);
      try {
        const data = {
          phone_number: formData.phone_number,
          name: formData.name,
          age: formData.age,
          gender: formData.gender,
          county: formData.county,
          town: formData.town
        };

        const result = await callApi('/register', 'POST', data);

        if (result && result.status === 'error' && result.message === 'User already exists') {
          setRegistrationError('⚠️ User already exists. Proceeding to dashboard.');
          setUserExistsError(true);
          addNotification('⚠️ User already exists. Proceeding to dashboard.', 'warning');

          const partialUser = {
            phone: formData.phone_number || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi',
            county: formData.county || 'Nairobi'
          };
          setCurrentUser(partialUser);
          setIsLoggedIn(true);
          setShowMainMenu(true);
          setIsFirstTimeUser(false);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          setMyPhone(formData.phone_number || '0712345678');
          setIsLoading(false);
          return;
        }

        if (result && result.status === 'success') {
          setMyPhone(formData.phone_number || '0712345678');
          setCompletedSteps(prev => new Set([...prev, currentStep]));
          addNotification('✅ Registration complete!');

          const newUser = {
            phone: formData.phone_number || '0712345678',
            name: formData.name || 'User',
            age: formData.age || '26',
            town: formData.town || 'Nairobi',
            county: formData.county || 'Nairobi'
          };
          setCurrentUser(newUser);
          setIsLoggedIn(true);
          setShowMainMenu(true);
          setIsFirstTimeUser(false);
          setIsLoading(false);
          return;
        } else {
          const errorMsg = result?.message || 'Registration failed. Please try again.';
          setRegistrationError(errorMsg);
          addNotification('❌ ' + errorMsg, 'error');
          setIsLoading(false);
          return;
        }
      } catch (error) {
        console.error('Registration error:', error);
        setRegistrationError('Network error. Please try again.');
        addNotification('❌ Network error', 'error');
        setIsLoading(false);
        return;
      }
    }

    // For other steps, just go to next
    if (currentStep < STEPS.length - 1) {
      setCurrentStep(currentStep + 1);
    }
  };

  // ============================================
  // RENDER ACTIVATION PAGE
  // ============================================

  const renderActivationPage = () => {
    return (
      <div className="activation-container">
        <div className="activation-card">
          <div className="activation-header">
            <span className="activation-icon">💑</span>
            <h1>PENZI Dating</h1>
            <p className="subtitle">Find your perfect match</p>
          </div>

          <div className={`server-status ${serverStatus}`}>
            <span className="status-dot"></span>
            <span className="status-text">
              {serverStatus === 'connected' ? '✅ Server Connected' : 
               serverStatus === 'checking' ? '⏳ Checking...' : 
               '❌ Server Not Connected'}
            </span>
          </div>

          {!activationDone ? (
            <>
              <div className="activation-keyword-display">
                <span className="keyword-label">📱 Activation Keyword</span>
                <span className="keyword-code">PENZI</span>
                <span className="keyword-hint">Enter this keyword to activate the service</span>
              </div>

              <div className="activation-input-group">
                <label>Enter Activation Code</label>
                <input
                  type="text"
                  value={activationKeyword}
