              </div>

              {errorDetails && (
                <div className="error-details">
                  <p className="error-detail-text">💡 {errorDetails}</p>
                </div>
              )}

              {responseMessage && (
                <div className={`response-message ${isSuccess ? 'success' : 'error'}`}>
                  {responseMessage}
                </div>
              )}
            </>
          ) : (
            <div className="activation-success-container">
              <span className="activation-success-icon">✅</span>
              <p className="activation-success-text">Service Activated!</p>
              <p className="activation-success-sub">Welcome to PENZI Dating</p>

              <button onClick={proceedToRegistration} className="btn-start">
                🚀 START
              </button>
            </div>
          )}
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER REGISTRATION STEPS
  // ============================================

  const renderRegistrationStep = () => {
    const step = STEPS[currentStep];
    const isLastStep = currentStep === STEPS.length - 1;
    const showUserExistsWarning = currentStep === 1 && userExistsError;
    const isStepCompleted = completedSteps.has(currentStep);
    const hasFields = step.fields && step.fields.length > 0;
    const previewSms = buildSmsPreview(step);
    const isFirstRegistrationStep = currentStep === 1;

    return (
      <div className="registration-container">
        <div className="registration-card">
          <div className="registration-header">
            <span className="registration-icon">{step.icon}</span>
            <h1>PENZI Dating</h1>
            <p className="subtitle">{step.subtitle}</p>
          </div>

          {activationDone && (
            <div className="progress-bar-container">
              <div className="progress-bar">
                <div className="progress-fill" style={{ width: `${getProgress()}%` }}></div>
              </div>
              <span className="progress-text">{getProgress()}% Complete • {completedSteps.size}/{STEPS.length - 1}</span>
            </div>
          )}

          {/* Show system response only on the first registration step */}
          {isFirstRegistrationStep && showSystemResponse && systemResponseMessage && (
            <div className="system-response-card">
              <div className="response-title">📨 System Response</div>
              <div className="response-body">{systemResponseMessage}</div>
